package io.github.astelev.around_planet.space;
import java.util.*;
/** Moving sphere intersections followed by independent, primary-relative Kepler conics. */
public final class PatchedConics {
    public record Leg(SpaceTrajectory path,long from,long until,boolean transition){}
    public record Flight(List<Leg> legs,SpaceTrajectory finalPath){public Flight{legs=List.copyOf(legs);}}
    public static SpaceTrajectory change(SpaceTrajectory path,long tick,CelestialSystem system){var global=system.global(path.primary(),path.at(tick),tick);String next=CelestialSystem.MOON.equals(path.primary())?CelestialSystem.EARTH:CelestialSystem.MOON;return new SpaceTrajectory(next,tick,system.relative(next,global,tick),system.mu(next));}
    public static Flight trace(SpaceTrajectory path,long from,long until,CelestialSystem system){var legs=new ArrayList<Leg>();if(system==null||!system.managed(path.primary()))return new Flight(List.of(new Leg(path,from,until,false)),path);for(int i=0;i<32;i++){long event=transition(path,from,until,system);if(event<0){legs.add(new Leg(path,from,until,false));return new Flight(legs,path);}legs.add(new Leg(path,from,event,true));path=change(path,event,system);from=event;if(from>=until)return new Flight(legs,path);}throw new IllegalArgumentException("Too many sphere transitions in one prediction");}
    public static long transition(SpaceTrajectory path,long from,long until,CelestialSystem system){if(until<from)return -1;return CelestialSystem.MOON.equals(path.primary())?exit(path,from,until,system.soi()):entry(path,from,until,system);}
    private static long exit(SpaceTrajectory path,long from,long until,double shell){var start=path.at(from);if(start.position().length()>shell+1e-4||start.position().length()>=shell-1e-6&&start.position().dot(start.velocity())>0)return from;double end=(until-from)/20.0;if(end<=0)return -1;var ellipse=EllipticArc.of(start,path.mu());double lo=0,hi=-1;if(ellipse!=null){double seconds=ellipse.outwardCrossing(shell);if(!Double.isFinite(seconds))return -1;long tick=from+Math.max(1,(long)Math.ceil(seconds*20-1e-8));return tick<=until?tick:-1;}else{hi=Math.min(end,Math.max(.05,shell/Math.max(1,start.velocity().length())));for(int i=0;i<64&&path.afterSeconds((from-path.epochTick())/20.0+hi).position().length()<shell;i++){if(hi>=end)return -1;lo=hi;hi=Math.min(end,hi*2);}}
        if(lo>end)return -1;for(int i=0;i<48;i++){double mid=(lo+hi)/2;if(path.afterSeconds((from-path.epochTick())/20.0+mid).position().length()<shell)lo=mid;else hi=mid;}long tick=from+Math.max(1,(long)Math.ceil(hi*20-1e-8));return tick<=until?tick:-1;}
    private static long entry(SpaceTrajectory path,long from,long until,CelestialSystem system){double elapsed=0,end=(until-from)/20.0;var initial=path.at(from);var m=system.moon(from);double gap=initial.position().subtract(m.position()).length()-system.soi();if(gap < -1e-5)return from;
        // Outside Earth the acceleration bound is finite. Conservative steps cannot skip a narrow encounter.
        double acceleration=system.earthMu()/(system.earthRadius()*system.earthRadius())+system.earthMu()/(system.distance()*system.distance());
        for(int i=0;i<8192;i++){var state=path.afterSeconds((from-path.epochTick())/20.0+elapsed);double inner=system.distance()-system.soi(),outer=system.distance()+system.soi(),radius=state.position().length();if(radius<inner-.001||radius>outer+.001){var ellipse=EllipticArc.of(state,path.mu());if(ellipse!=null){double jump=radius<inner?ellipse.outwardCrossing(inner):ellipse.inwardCrossing(outer);if(!Double.isFinite(jump)||elapsed+jump>end)return -1;if(jump>.00001){elapsed+=jump;continue;}}else if(radius>outer&&state.position().dot(state.velocity())>=0)return -1;}var moon=system.moonSeconds(from/20.0+elapsed);var relative=state.position().subtract(moon.position());gap=relative.length()-system.soi();var v=state.velocity().subtract(moon.velocity());if(gap<=.001&&relative.dot(v)<0){long tick=from+Math.max(1,(long)Math.ceil(elapsed*20));return tick<=until?tick:-1;}if(elapsed>=end)return -1;if(gap<=.001){elapsed=Math.min(end,elapsed+.05);continue;}double speed=v.length(),step=.8*2*Math.max(.00001,gap)/(speed+Math.sqrt(speed*speed+2*acceleration*Math.max(.00001,gap)));if(step<1e-7)return -1;elapsed=Math.min(end,elapsed+step);}
        throw new IllegalArgumentException("Encounter search budget exceeded");
    }
    private PatchedConics(){}
}
